#!/usr/bin/env bash
# stages libmpv for macOS, bundled + hard-linked + fully self-contained on
# BOTH architectures - end users never need homebrew (or anything else)
# installed to run charnel.
#
# arm64: bundles homebrew's REAL mpv build (`brew install mpv` against the
# system /opt/homebrew prefix) into
# client/charnel/src-tauri/mpv-runtime/lib (referenced by
# tauri.macos.conf.json's `bundle.macOS.frameworks`, regenerated by this
# script every run since the exact dependency filenames drift with
# homebrew's own package versions).
#
# x86_64: homebrew dropped bottle (prebuilt binary) support for Intel
# macOS entirely as of ~September 2026 (`brew install mpv` now prints an
# explicit "we do not provide support for this platform" warning) - but
# building from source still works fine (requires a full Xcode.app
# install, not just the Command Line Tools - `deno`, a transitive
# dependency via yt-dlp, and `molten-vk` both refuse to build without
# it). it's ~86 formulas deep (ffmpeg, libplacebo, llvm, rust, ... - a
# multi-hour build the first time). bootstraps its own relocatable
# homebrew prefix at /Users/Shared/freqhole-homebrew-x86 (homebrew
# refuses to run from /tmp, see git history) rather than touching the
# system /usr/local, and runs every brew command under `arch -x86_64`
# (rosetta) since this machine's real arch is whatever `uname -m` says,
# not necessarily x86_64.
#
# both architectures' bundled dylib closures get committed to git under
# mpv-runtime/committed/<arch> once built (see stage_from_committed
# below) - CI and fresh local checkouts reuse that committed snapshot by
# default instead of redoing the slow homebrew build every single run.
#
# both architectures' mpv dependency closure (ffmpeg, libass, libplacebo,
# ~45-90 dylibs) has absolute install names pointing at wherever homebrew
# put them, not portable as-is - `dylibbundler` copies the whole closure
# into one flat directory and rewrites every install name to be
# @loader_path-relative, making it fully self-contained. see
# `bundle_mpv_dylib_closure` below (shared by both arch branches).
#
# history: this used to be a from-scratch weak-linking setup for x86_64
# (optional libmpv, never bundled) after both the prebuilt
# `mpv-libre-runtime` project AND homebrew's arm64 mpv build appeared to
# have a broken Vulkan-only GPU renderer on macOS (`vid=no`/`current-vo`
# unavailable, `VK_ERROR_INCOMPATIBLE_DRIVER` even with a real MoltenVK
# ICD explicitly supplied). confirmed for real later (2026-09-30) that
# this was never actually a broken renderer at all - it was macOS
# hardened runtime's Library Validation blocking `dlopen` of the
# ad-hoc-signed MoltenVK dylib the vulkan loader needs at runtime (fixed
# via `com.apple.security.cs.disable-library-validation` in
# client/charnel/src-tauri/macos/entitlements.plist). once that was
# understood, bundling homebrew's real mpv (arm64) and building mpv from
# source (x86_64) both just worked.
#
# usage: scripts/fetch-mpv-runtime.sh <arm64|x86_64> [--rebuild] [--force]
#
# by default, if client/charnel/src-tauri/mpv-runtime/committed/<arch>
# already has a bundled dylib closure checked into git, this just copies
# it into place (seconds, no homebrew/network/compiler needed at all) -
# pass --rebuild to force redoing the real homebrew fetch+build+bundle
# below and refresh that committed snapshot (e.g. to pick up a newer mpv
# release). --rebuild alone only forces ffmpeg+mpv themselves to
# reinstall (x86_64) - already-installed dependencies (x265,
# libplacebo, etc.) are left alone and reused as-is, so a run that fails
# partway through (e.g. one unrelated formula's build breaking) can
# just be rerun to pick up where it left off instead of redoing
# everything. pass --force too (x86_64 only) on the rare occasion
# something needs EVERY dependency recompiled from scratch (e.g. a
# change to the global cc/ld shim patch below, which only affects
# formulae that actually get recompiled under it) - wipes every formula
# currently installed in the dedicated x86_64 prefix first.
set -euo pipefail

ARCH="${1:?usage: fetch-mpv-runtime.sh <arm64|x86_64> [--rebuild] [--force]}"
REBUILD="${2:-}"
FORCE="${3:-}"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
BUNDLE_DEST="$REPO_ROOT/client/charnel/src-tauri/mpv-runtime/lib"
COMMITTED_DIR="$REPO_ROOT/client/charnel/src-tauri/mpv-runtime/committed/$ARCH"
CONF_PATH="$REPO_ROOT/client/charnel/src-tauri/tauri.macos.conf.json"

# regenerates tauri.macos.conf.json to reference every dylib currently in
# $BUNDLE_DEST - shared by both the committed-snapshot fast path and the
# real bundle_mpv_dylib_closure slow path below.
#
# $1: "true" to also set bundle.macOS.minimumSystemVersion to 14.0 (x86_64
#     only - arm64's rustc default of 11.0 is already fine).
regen_tauri_conf() {
    local need_min_version="$1"
    python3 - "$BUNDLE_DEST" "$CONF_PATH" "$need_min_version" <<'PYEOF'
import json
import os
import sys

bundle_dest, conf_path, need_min_version = sys.argv[1], sys.argv[2], sys.argv[3]
entries = sorted(os.listdir(bundle_dest))
dylibs = [f for f in entries if f.endswith(".dylib")]
# tauri's `bundle.macOS.frameworks` requires actual dylibs/.frameworks -
# the MoltenVK ICD manifest (plain json) and the bundled ffmpeg/ffprobe
# CLI binaries (plain executables, no extension) are all read/exec'd at
# runtime rather than something macOS treats as a loadable framework, so
# they belong under `bundle.resources` instead (rejected with "Framework
# path should have .framework extension" otherwise).
resources = [f for f in entries if f.endswith(".json") or f in ("ffmpeg", "ffprobe")]
conf = {
    "build": {"beforeBundleCommand": "scripts/fixup-mpv-install-name.sh"},
    "bundle": {
        "macOS": {"frameworks": [f"mpv-runtime/lib/{f}" for f in dylibs]},
        "resources": [f"mpv-runtime/lib/{f}" for f in resources],
    },
}
if need_min_version == "true":
    conf["bundle"]["macOS"]["minimumSystemVersion"] = "14.0"
with open(conf_path, "w") as fh:
    json.dump(conf, fh, indent=2)
    fh.write("\n")
PYEOF
}

# copies the committed/<arch> snapshot into $BUNDLE_DEST - the fast path,
# used whenever that snapshot exists and --rebuild wasn't passed.
#
# $1: "true" to set bundle.macOS.minimumSystemVersion (see regen_tauri_conf).
# $2: optional - if set, also stage libmpv.2.dylib (+ unversioned symlink)
#     at this path, so `cargo build`'s `-lmpv` linker step (e.g. rathole,
#     which links libmpv directly rather than bundling it tauri-style)
#     has a real file to resolve against without needing a real `brew
#     install mpv` ever run on this machine - both arches use this (see
#     each branch below for the path): arm64's committed fast path never
#     installs homebrew's real mpv at all, so it needs this just as much
#     as x86_64 does.
stage_from_committed() {
    local need_min_version="$1"
    local linker_stub_dir="${2:-}"

    rm -rf "$BUNDLE_DEST"
    mkdir -p "$BUNDLE_DEST"
    cp "$COMMITTED_DIR"/*.dylib "$BUNDLE_DEST/"
    # MoltenVK's ICD manifest (see bundle_mpv_dylib_closure) - not every
    # committed/<arch> snapshot necessarily has one yet, so don't fail if
    # the glob matches nothing.
    cp "$COMMITTED_DIR"/*.json "$BUNDLE_DEST/" 2>/dev/null || true
    # bundled ffmpeg/ffprobe CLI binaries (see bundle_mpv_dylib_closure) -
    # same "not every snapshot has one yet" caveat as the json manifest.
    cp "$COMMITTED_DIR/ffmpeg" "$COMMITTED_DIR/ffprobe" "$BUNDLE_DEST/" 2>/dev/null || true
    # homebrew-built dylibs are mode 444 - tauri-bundler's xattr/codesign
    # steps need write access to touch them at all.
    chmod u+w "$BUNDLE_DEST"/*.dylib
    chmod u+w "$BUNDLE_DEST/ffmpeg" "$BUNDLE_DEST/ffprobe" 2>/dev/null || true
    regen_tauri_conf "$need_min_version"

    if [ -n "$linker_stub_dir" ]; then
        # this stub only exists so cargo's `-lmpv` has a real file to
        # resolve against on a machine with no real homebrew mpv install
        # at all (see this function's own doc comment above). if
        # $linker_stub_dir already resolves into a real Cellar keg (i.e.
        # homebrew's own `brew link` put a real symlink here from an
        # actual `brew install mpv`), NEVER write through it: doing so
        # permanently overwrites a pristine homebrew-built dylib with
        # whatever's in committed/$ARCH - which, if that snapshot is
        # stale (e.g. an interrupted previous run of this very script),
        # silently corrupts the real Cellar build too. confirmed real
        # 2026-10-06: an interrupted `fetch-mpv-runtime.sh x86_64` left
        # committed/x86_64 stale, and the NEXT run's fast path clobbered
        # a freshly-fixed real mpv Cellar build with that stale snapshot
        # via this exact write-through, resurrecting an already-fixed
        # bug. a plain `mkdir -p` target (no real brew install present)
        # is the only case this stub is actually for.
        real_path="$(cd "$linker_stub_dir" 2>/dev/null && pwd -P || true)"
        if [ -f "$linker_stub_dir/libmpv.2.dylib" ] && [[ "$real_path" == *"/Cellar/"* ]]; then
            echo "fetch-mpv-runtime: $linker_stub_dir resolves into a real homebrew Cellar keg - leaving its libmpv.2.dylib alone instead of overwriting with the committed/$ARCH snapshot"
        else
            mkdir -p "$linker_stub_dir"
            # homebrew-built dylibs are mode 444 (read-only) - `cp` propagates
            # that, and a stale copy from a previous run would then make a
            # plain `cp`/`ln -sf` here fail outright. `rm -f` only needs the
            # *directory* to be writable (not the target file itself), so
            # always clear these two files first rather than relying on them
            # not existing yet.
            rm -f "$linker_stub_dir/libmpv.2.dylib" "$linker_stub_dir/libmpv.dylib"
            cp -f "$COMMITTED_DIR/libmpv.2.dylib" "$linker_stub_dir/"
            chmod u+w "$linker_stub_dir/libmpv.2.dylib"
            ln -sf libmpv.2.dylib "$linker_stub_dir/libmpv.dylib"
        fi
    fi

    count=$(find "$BUNDLE_DEST" -name '*.dylib' | wc -l | tr -d ' ')
    echo "fetch-mpv-runtime: staged $count dylibs from committed/$ARCH (pass --rebuild to refresh from a fresh homebrew build)"
}

# bundles a built mpv dylib (and its full dependency closure) into
# $BUNDLE_DEST, regenerates tauri.macos.conf.json, and refreshes
# committed/<arch> so future runs can skip straight to the fast path
# above - shared by both arch branches below, which differ only in HOW
# they get homebrew's mpv built/installed in the first place.
#
# $1: path to the homebrew-built libmpv.2.dylib to bundle.
# $2: "true" to also set bundle.macOS.minimumSystemVersion to 14.0 in the
#     generated config (x86_64 only - arm64's rustc default of 11.0 is
#     already fine).
# $3: brew invocation to use for `--prefix molten-vk` lookups (e.g. "brew"
#     or `arch -x86_64 /path/to/brew`) - word-split unquoted below, so
#     must not itself contain anything needing quoting/escaping.
bundle_mpv_dylib_closure() {
    local src_mpv_dylib="$1"
    local need_min_version="$2"
    local brew_cmd="$3"

    if ! command -v dylibbundler >/dev/null 2>&1; then
        echo "fetch-mpv-runtime: installing dylibbundler via homebrew..."
        brew install dylibbundler
    fi

    rm -rf "$BUNDLE_DEST"
    mkdir -p "$BUNDLE_DEST"
    cp "$src_mpv_dylib" "$BUNDLE_DEST/"
    chmod u+w "$BUNDLE_DEST"/*.dylib

    # flat directory + uniform @loader_path/ for every rewrite (not
    # @loader_path/Frameworks/ or similar): dylibbundler rewrites every
    # dependency's references using the SAME -p prefix regardless of
    # whether that dependency itself lives at the top level or is a
    # dependency-of-a-dependency already inside -d's directory - a nested
    # prefix doubles up (Frameworks/Frameworks/...) for anything but the
    # top-level -x target. keeping everything in one flat dir with a bare
    # @loader_path/ sidesteps that entirely.
    (cd "$BUNDLE_DEST" && dylibbundler -b -of -cd -x libmpv.2.dylib -d . -p "@loader_path/" </dev/null)

    # dylibbundler adds an @loader_path/ rpath to the -x target that's
    # entirely redundant (every rewritten reference already uses an
    # explicit @loader_path/<name> path, not @rpath/<name>) and, for
    # reasons not fully understood, sometimes adds it twice - a literal
    # duplicate LC_RPATH load command, which ld refuses to link against
    # ("duplicate LC_RPATH") once anything depends on this dylib. strip it.
    for f in "$BUNDLE_DEST"/*.dylib; do
        count=$(otool -l "$f" | grep -c "path @loader_path/ (offset" || true)
        if [ "$count" -gt 1 ]; then
            install_name_tool -delete_rpath "@loader_path/" "$f"
        fi
    done

    # the -x target's own install name (id) is untouched by dylibbundler -
    # still homebrew's absolute path. rewrite it so it's resolvable once
    # bundled - client/charnel/scripts/fixup-mpv-install-name.sh separately
    # rewrites OUR OWN executable's reference to this same file (baked in
    # at link time from this exact string) to
    # @executable_path/../Frameworks/libmpv.2.dylib.
    install_name_tool -id "@loader_path/libmpv.2.dylib" "$BUNDLE_DEST/libmpv.2.dylib"

    # every install_name_tool edit above invalidates whatever signature was
    # there before (homebrew's own, or none) - ad-hoc re-sign so dyld's
    # runtime validation doesn't refuse to load these (confirmed for real:
    # an unsigned/invalidated dylib gets the whole process SIGKILLed with
    # zero diagnostic output at all, easy to mistake for a rendering bug).
    codesign --force --sign - "$BUNDLE_DEST"/*.dylib

    # MoltenVK (the actual vulkan ICD/driver) isn't a static dependency of
    # libmpv.2.dylib - mpv's vulkan vo finds it at runtime via the vulkan
    # LOADER's own ICD-manifest discovery (a json file pointing at the
    # dylib), not a normal dlopen of a linked dependency - so dylibbundler
    # never sees or bundles it, even though libvulkan.1.dylib (the loader
    # itself) gets swept up fine. without this, the bundled app has a
    # vulkan loader with no driver to find at all: every vo/gpu context
    # fails identically with VK_ERROR_INCOMPATIBLE_DRIVER (confirmed for
    # real 2026-10-02 via mpv's own verbose log - audio plays, no video
    # window, no error dialog). bundle the dylib as a `frameworks` entry
    # (ends up flat at Contents/Frameworks/) and the manifest as a
    # `resources` entry (tauri rejects non-.dylib/.framework paths under
    # `frameworks` - "Framework path should have .framework extension" -
    # but resources entries preserve their FULL given relative path
    # instead of flattening, landing at
    # Contents/Resources/mpv-runtime/lib/MoltenVK_icd.json, confirmed via
    # an actual local build 2026-10-02) - so `library_path` can't be a
    # bare filename (the vulkan loader resolves non-absolute paths
    # relative to the manifest's OWN directory, which is no longer the
    # same directory as the dylib once they're split across
    # Frameworks/Resources like this). client/charnel's own startup code
    # points $VK_ICD_FILENAMES at this bundled manifest before mpv ever
    # touches vulkan - see video_window/libmpv_backend.rs.
    local moltenvk_prefix
    moltenvk_prefix=$($brew_cmd --prefix molten-vk 2>/dev/null || true)
    if [ -n "$moltenvk_prefix" ] && [ -f "$moltenvk_prefix/lib/libMoltenVK.dylib" ]; then
        cp "$moltenvk_prefix/lib/libMoltenVK.dylib" "$BUNDLE_DEST/"
        chmod u+w "$BUNDLE_DEST/libMoltenVK.dylib"
        install_name_tool -id "@loader_path/libMoltenVK.dylib" "$BUNDLE_DEST/libMoltenVK.dylib"
        codesign --force --sign - "$BUNDLE_DEST/libMoltenVK.dylib"

        python3 - "$moltenvk_prefix/etc/vulkan/icd.d/MoltenVK_icd.json" "$BUNDLE_DEST/MoltenVK_icd.json" <<'PYEOF'
import json
import sys

src, dest = sys.argv[1], sys.argv[2]
with open(src) as f:
    manifest = json.load(f)
# Contents/Resources/mpv-runtime/lib/MoltenVK_icd.json (this file) ->
# Contents/Frameworks/libMoltenVK.dylib (3 levels up, then into Frameworks).
manifest["ICD"]["library_path"] = "../../../Frameworks/libMoltenVK.dylib"
with open(dest, "w") as f:
    json.dump(manifest, f, indent=4)
    f.write("\n")
PYEOF
    else
        echo "fetch-mpv-runtime: warning - molten-vk not found via '$brew_cmd --prefix molten-vk', bundled app's vulkan video output will not work" >&2
    fi

    # bundles ffmpeg/ffprobe (plain CLI binaries, used by grimoire's own
    # transcode/thumbnail/probe code via Command::new - a completely
    # separate code path from libmpv above) reusing THIS SAME dylib
    # closure, rather than a second independent copy of every ffmpeg lib -
    # confirmed for real 2026-10-02 that homebrew's standalone `ffmpeg`
    # formula (a direct dependency of `mpv`, always installed alongside
    # it) is ABI-compatible with mpv's own linked copies: matching
    # SONAMEs/compatibility versions, and a real `dylibbundler` pass
    # against the already-populated $BUNDLE_DEST correctly recognized
    # every dependency as already present (49 dylibs before, 49 after -
    # zero duplicates) and rewrote ffmpeg/ffprobe's references to them
    # directly, verified with a real libx264 encode + ffprobe decode in
    # the exact final bundle layout.
    #
    # ffmpeg/ffprobe are plain executables (no extension) - like
    # MoltenVK_icd.json above, tauri's `frameworks` key rejects them
    # ("Framework path should have .framework extension"), so they're
    # bundled as `resources` entries too, landing at
    # Contents/Resources/mpv-runtime/lib/{ffmpeg,ffprobe} (3 levels
    # removed from Contents/Frameworks/ where the dylibs actually live -
    # same nesting the MoltenVK manifest's library_path already accounts
    # for). client/charnel's own ffmpeg-path resolution prefers this
    # bundled copy, falling back to the user's own configured/PATH
    # ffmpeg if bundling failed or on non-macOS - see
    # grimoire/src/config.rs.
    local ffmpeg_prefix
    ffmpeg_prefix=$($brew_cmd --prefix ffmpeg 2>/dev/null || true)
    if [ -n "$ffmpeg_prefix" ] && [ -f "$ffmpeg_prefix/bin/ffmpeg" ] && [ -f "$ffmpeg_prefix/bin/ffprobe" ]; then
        cp "$ffmpeg_prefix/bin/ffmpeg" "$ffmpeg_prefix/bin/ffprobe" "$BUNDLE_DEST/"
        chmod u+w "$BUNDLE_DEST/ffmpeg" "$BUNDLE_DEST/ffprobe"
        # NOT dylibbundler here on purpose: pointing it at $BUNDLE_DEST (so
        # it recognizes the mpv closure as already-bundled) also makes it
        # re-rewrite THOSE dylibs' own inter-dependencies (e.g. libavcodec
        # -> libswresample) using ffmpeg/ffprobe's
        # @executable_path/../../../Frameworks/ prefix instead of leaving
        # their correct @loader_path/ references alone - confirmed for real
        # 2026-10-03 via a crash report: dyld refused to load libavcodec
        # because it looked for libswresample at
        # @executable_path/../../../Frameworks (3 levels up from
        # Contents/MacOS/charnel lands at /Applications/, not
        # Contents/Frameworks/). every dependency ffmpeg/ffprobe need is
        # already bundled under the same names (see comment above - zero
        # new dylibs), so just repoint their OWN load commands directly
        # instead of letting dylibbundler touch anything else.
        for bin in ffmpeg ffprobe; do
            f="$BUNDLE_DEST/$bin"
            while IFS= read -r dep; do
                case "$dep" in
                    /usr/lib/*|/System/*) continue ;;
                esac
                # homebrew deps are often referenced via an unversioned
                # SONAME symlink (e.g. libSvtAv1Enc.4.dylib) that doesn't
                # match the real, fully-versioned bundled filename
                # (libSvtAv1Enc.4.2.0.dylib) by basename alone - resolve
                # the symlink first so the lookup below matches what's
                # actually sitting in $BUNDLE_DEST.
                real_dep=$(python3 -c "import os,sys; print(os.path.realpath(sys.argv[1]))" "$dep" 2>/dev/null || echo "$dep")
                dep_name=$(basename "$real_dep")
                if [ -f "$BUNDLE_DEST/$dep_name" ]; then
                    install_name_tool -change "$dep" "@executable_path/../../../Frameworks/$dep_name" "$f"
                else
                    echo "fetch-mpv-runtime: warning - $bin depends on $dep, not found in $BUNDLE_DEST (left as-is)" >&2
                fi
            done < <(otool -L "$f" | tail -n +2 | awk '{print $1}')
            codesign --force --sign - "$f"
        done
    else
        echo "fetch-mpv-runtime: warning - ffmpeg not found via '$brew_cmd --prefix ffmpeg', bundled app will fall back to the user's own ffmpeg/ffprobe install" >&2
    fi

    regen_tauri_conf "$need_min_version"

    # refresh the committed snapshot so future runs (CI included) can use
    # the fast path above instead of rebuilding mpv from source again.
    rm -rf "$COMMITTED_DIR"
    mkdir -p "$COMMITTED_DIR"
    cp "$BUNDLE_DEST"/*.dylib "$COMMITTED_DIR/"
    cp "$BUNDLE_DEST"/*.json "$COMMITTED_DIR/" 2>/dev/null || true
    cp "$BUNDLE_DEST/ffmpeg" "$BUNDLE_DEST/ffprobe" "$COMMITTED_DIR/" 2>/dev/null || true

    count=$(find "$BUNDLE_DEST" -name '*.dylib' | wc -l | tr -d ' ')
    echo "fetch-mpv-runtime: bundled $count dylibs from homebrew's mpv, regenerated $CONF_PATH, refreshed committed/$ARCH"
}

case "$ARCH" in
  arm64)
    if [ -d "$COMMITTED_DIR" ] && [ "$REBUILD" != "--rebuild" ]; then
      # /Users/Shared (world-writable, no sudo needed, not per-user like
      # $HOME - same reasoning as x86_64's stub dir below) matches a
      # second `.cargo/config.toml` rustflags `-L` entry for this target -
      # a clean CI runner never runs `brew install mpv` on this fast
      # path, so without this, rathole's `-lmpv` has nothing to resolve
      # against (confirmed for real 2026-10-02: `make build-mac-arm`
      # failed in CI with "library 'mpv' not found" despite charnel's own
      # bundling succeeding, since charnel only needs the dylib *copied*
      # into its app bundle, never linked against at compile time).
      # /usr/local/lib (this target's other `-L` entry) would also work on
      # CI's runner but needs sudo on a normal dev mac, so this dedicated
      # path is used instead - safe to pass unconditionally either way.
      stage_from_committed false "/Users/Shared/freqhole-mpv-arm64/lib"
      exit 0
    fi

    if ! [ -f /opt/homebrew/opt/mpv/lib/libmpv.2.dylib ]; then
      echo "fetch-mpv-runtime: installing mpv via homebrew..."
      brew install mpv
    fi
    bundle_mpv_dylib_closure /opt/homebrew/opt/mpv/lib/libmpv.2.dylib false brew
    ;;

  x86_64)
    if [ -d "$COMMITTED_DIR" ] && [ "$REBUILD" != "--rebuild" ]; then
      # same fixed path .cargo/config.toml's x86_64 rustflags point `-L`
      # at - stage_from_committed drops libmpv.2.dylib there too so
      # `cargo build --target x86_64-apple-darwin`'s `-lmpv` resolves
      # without needing homebrew (or any build) at all.
      #
      # `need_min_version` is now always false - mpv is weakly linked,
      # so a missing/incompatible bundled copy on an old macOS no longer
      # needs the APP ITSELF to refuse to launch; it just means
      # `is_libmpv_available()`'s dlsym check comes back false there and
      # the fallback player is used instead.
      stage_from_committed false "/Users/Shared/freqhole-homebrew-x86/opt/mpv/lib"
      exit 0
    fi

    # homebrew refuses to run from a prefix inside its own temp directory
    # (anything under /tmp) - this is a real, persistent, relocatable
    # install (not a throwaway), so /Users/Shared (world-writable on every
    # mac, no sudo needed, NOT per-user like $HOME) is the right home for
    # it: a fixed, known-at-config-write-time path is required since
    # .cargo/config.toml's rustflags are static strings with no shell/env
    # expansion, and this same path needs to agree with the one baked in
    # there. cacheable across CI runs (actions/cache keyed on this path
    # avoids re-running the ~86-formula from-source build every single
    # release) and persists across local dev sessions the same way the
    # arm64 branch's system /opt/homebrew already does.
    BREW_PREFIX="/Users/Shared/freqhole-homebrew-x86"
    if ! [ -x "$BREW_PREFIX/bin/brew" ]; then
      echo "fetch-mpv-runtime: bootstrapping a relocatable x86_64 homebrew at $BREW_PREFIX..."
      mkdir -p "$BREW_PREFIX"
      curl -fsSL https://github.com/Homebrew/brew/tarball/main \
        | tar xz --strip-components 1 -C "$BREW_PREFIX"
    fi

    # modern homebrew resolves `brew info`/`brew install` through a
    # remote JSON API by default and keeps no local formula .rb files at
    # all - fine for installing, but `brew cat mpv` (used below to seed
    # our patched tap) literally cats the on-disk formula file, so it
    # silently prints nothing (exit 0, zero bytes) without a real local
    # homebrew/core clone. `brew tap homebrew/core` alone also no-ops
    # ("no longer typically necessary") - `--force` is required to
    # actually get the clone. confirmed for real 2026-10-05.
    if ! [ -d "$BREW_PREFIX/Library/Taps/homebrew/homebrew-core" ]; then
      echo "fetch-mpv-runtime: force-tapping homebrew/core locally (brew cat needs a real formula file on disk, not just the API)..."
      arch -x86_64 "$BREW_PREFIX/bin/brew" tap homebrew/core --force
    fi

    # two self-healing checks, both confirmed real 2026-10-07 and both
    # cheap/idempotent enough to just always run rather than trusting
    # a human to remember them:
    #
    # 1. a keg left over from an interrupted previous install (e.g. a
    #    formula that failed partway through its own `install` method)
    #    can have read-only (444) files, which then blocks a later
    #    reinstall's `cp`/`install` step with "Permission denied" even
    #    though the current user owns the file and its containing
    #    directory - libvpx's `vpx.pc` hit this exactly.
    if [ -d "$BREW_PREFIX/Cellar" ]; then
      chmod -R u+w "$BREW_PREFIX/Cellar" 2>/dev/null || true
    fi
    # 2. a keg-only formula (e.g. libarchive, which conflicts with
    #    macOS's own bundled tar/cpio) whose install got interrupted
    #    before `brew link` ran leaves its Cellar files fully present
    #    but with NO `opt/<formula>` symlink at all - anything that
    #    resolves the dependency through `opt/` (dylibbundler included)
    #    then can't find it, and dylibbundler's interactive "does not
    #    exist, try again" prompt loops forever since nothing is there
    #    to answer it non-interactively. re-link anything missing it.
    for keg_dir in "$BREW_PREFIX"/Cellar/*/; do
      [ -d "$keg_dir" ] || continue
      formula_name=$(basename "$keg_dir")
      if ! [ -e "$BREW_PREFIX/opt/$formula_name" ]; then
        echo "fetch-mpv-runtime: $formula_name is installed but missing its opt/ symlink (likely an interrupted install) - re-linking..."
        arch -x86_64 "$BREW_PREFIX/bin/brew" link --force --overwrite "$formula_name" >/dev/null 2>&1 || true
      fi
    done

    # per-formula ENV["MACOSX_DEPLOYMENT_TARGET"] patches (see ffmpeg/mpv
    # below) only ever cover the ONE formula they're applied to - mpv
    # pulls in ~86 formulae total (ffmpeg, then x265 confirmed real
    # 2026-10-07, and likely more after that: libplacebo, dav1d, libvpx,
    # x264, libass, etc.), each independently built from source against
    # whatever macOS this machine happens to be running, and each
    # capable of embedding the exact same class of "built for Mac OS X
    # <host-version>" symbol that's missing on a real macOS 12.0
    # (Monterey, charnel's actual minimum) target - patching them one at
    # a time as each one surfaces a crash is not scalable.
    #
    # homebrew's own `cc`/`clang`/`ld` shim (every single compiler and
    # linker invocation, for every formula, is routed through this one
    # script - that's the entire point of superenv) only ever RAISES an
    # explicit `-mmacosx-version-min=` flag up to a floor
    # (HOMEBREW_MACOS_OLDEST_ALLOWED, see `refurbish_arg` in this file) -
    # there is no existing homebrew mechanism to LOWER one, and most
    # build systems (cmake, meson, a bare `clang` invocation with no
    # explicit flag at all) just default to whatever `sw_vers` reports
    # for the host when nothing else overrides it. patching this ONE
    # file directly (part of our own disposable, relocatable x86_64
    # homebrew clone - never touches the user's real arm64 homebrew) to
    # unconditionally force `-mmacosx-version-min=12.0` (compile/link)
    # or `-macosx_version_min 12.0` (raw `ld`) onto every invocation
    # closes this for the ENTIRE dependency graph in one shot, instead
    # of reactively patching formulae one at a time as each new one
    # surfaces the same bug.
    CC_SHIM="$BREW_PREFIX/Library/Homebrew/shims/super/cc"
    if [ -f "$CC_SHIM" ] && ! grep -q "freqhole: force macOS 12.0 deployment target" "$CC_SHIM"; then
      echo "fetch-mpv-runtime: patching homebrew's cc/ld shim to force a macOS 12.0 deployment target on every compile/link, for every formula..."
      python3 - "$CC_SHIM" <<'PYEOF'
import sys

path = sys.argv[1]
with open(path) as f:
    content = f.read()
marker = "    optional_args + @positional_args\n  end"
if marker not in content:
    print(f"fetch-mpv-runtime: cc shim patch failed - expected marker not found in {path}", file=sys.stderr)
    sys.exit(1)
patch = (
    "    # freqhole: force macOS 12.0 deployment target on every\n"
    "    # compile/link, for every formula (see fetch-mpv-runtime.sh).\n"
    "    if mac?\n"
    "      if [:cc, :cxx, :ccld, :cxxld].include?(mode)\n"
    "        optional_args << \"-mmacosx-version-min=12.0\"\n"
    "      elsif mode == :ld\n"
    "        optional_args << \"-macosx_version_min\" << \"12.0\"\n"
    "      end\n"
    "    end\n\n"
    "    optional_args + @positional_args\n  end"
)
content = content.replace(marker, patch, 1)
with open(path, "w") as f:
    f.write(content)
PYEOF
    fi

    # the cc shim patch above only affects formulae that actually get
    # RECOMPILED - `brew install ffmpeg` doesn't rebuild ffmpeg's own
    # already-satisfied dependencies (x265 included) just because ffmpeg
    # itself reinstalled, so a formula built in an EARLIER run (before
    # this patch existed) keeps its old, wrongly-targeted dylib forever
    # unless something forces it to rebuild too (confirmed real
    # 2026-10-07: x265 kept crashing, "built for Mac OS X 15.0", on a
    # rebuild that only force-reinstalled ffmpeg+mpv). this x86_64
    # prefix exists solely for mpv + its dependency closure + dylibbundler
    # (nothing else is ever installed into it), so `--force` wipes every
    # formula currently installed here and lets the ffmpeg/mpv installs
    # below pull them all back in fresh, guaranteeing every single dylib
    # in the chain is actually recompiled under the corrected shim - not
    # just the two formulae this script happens to patch directly.
    # deliberately separate from plain `--rebuild` (which leaves
    # already-installed dependencies alone): an unrelated formula failing
    # mid-build (e.g. vapoursynth's own packaging bug, confirmed real
    # 2026-10-07) shouldn't force every OTHER already-correctly-rebuilt
    # dependency to redo a multi-hour compile too - just rerun with
    # `--rebuild` alone to resume, reusing whatever already succeeded.
    if [ "$FORCE" = "--force" ]; then
      INSTALLED_FORMULAE=$(arch -x86_64 "$BREW_PREFIX/bin/brew" list --formula 2>/dev/null)
      if [ -n "$INSTALLED_FORMULAE" ]; then
        echo "fetch-mpv-runtime: --force requested - wiping all currently installed x86_64 formulae (mpv's full dependency closure, e.g. x265) so every dylib is recompiled under the corrected cc shim..."
        # shellcheck disable=SC2086
        arch -x86_64 "$BREW_PREFIX/bin/brew" uninstall --force --ignore-dependencies $INSTALLED_FORMULAE
      fi
    fi

